import { Badge } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { StickyBar } from '@refy-design/web';
import { useState } from 'react';
function StickyBarExample() {
  const [approved, setApproved] = useState(false);
  return (
    <StickyBar
      title="Material review"
      status={
        <Badge tone={approved ? 'success' : 'warn'}>
          {approved ? 'Approved' : 'In review'}
        </Badge>
      }
      actions={
        <Button onClick={() => setApproved(!approved)}>
          {approved ? 'Reopen review' : 'Approve material'}
        </Button>
      }
    />
  );
}
export function Example() {
  return <StickyBarExample />;
}
